import{_ as a,o as t,c as r,a5 as i}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Debug Tool: Heightmap Replacement","description":"","frontmatter":{},"headers":[],"relativePath":"sections/debug_tools/rayrai_heightmap_replacement.md","filePath":"sections/debug_tools/rayrai_heightmap_replacement.md"}'),o={name:"sections/debug_tools/rayrai_heightmap_replacement.md"};function n(s,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="debug-tool-heightmap-replacement" tabindex="-1">Debug Tool: Heightmap Replacement <a class="header-anchor" href="#debug-tool-heightmap-replacement" aria-label="Permalink to &quot;Debug Tool: Heightmap Replacement&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Checks rayrai depth images for stale geometry after removing heightmaps and primitives. The scene places a PD-controlled ANYmal on a flat terrain patch and renders its front and rear depth cameras into separate ImGui panels, and draws the pixels of each camera projected into the world as small instanced cubes. Press Space to create a visibly different heightmap with broad mounds that shift across both camera frames, then replace randomized populations of simple primitives and delete the old scene.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_heightmap_replacement</code>. Source: <code>examples/tools/debug/rayrai_heightmap_replacement.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Build with <code>RAISIM_DEBUG_TOOLS=ON</code> as described in <a href="./../DebugTools.html">Regression and Debug Tools</a>, then run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-debug/examples/rayrai_heightmap_replacement</span></span></code></pre></div><p>On Windows, run <code>build-debug\\bin\\rayrai_heightmap_replacement.exe</code> instead. This tool renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="how-to-reproduce" tabindex="-1">How to reproduce <a class="header-anchor" href="#how-to-reproduce" aria-label="Permalink to &quot;How to reproduce&quot;">​</a></h2><ol><li>Watch the mounds in the front and rear depth images shown at the upper left.</li><li>Tap Space several times. Each press removes the current heightmap and creates a new generation with a random number of boxes, spheres, and cylinders in each camera frame.</li><li>Compare the depth image with the current colored terrain in the main view. A mound or primitive from an earlier generation indicates stale deleted geometry in the depth pass.</li><li>The projected pixel cubes must lie on the current terrain and primitives. Cubes floating in the air or buried in the ground show that the depth image does not match the scene.</li></ol><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Loads the sensored ANYmal used by <code>sensor_suite</code> and selects its front and rear depth cameras.</li><li>Uses PD gains and a nominal standing target to hold the twelve leg joints.</li><li>Keeps a radius of 1.15 m around the robot exactly flat, with a smooth transition to rolling terrain.</li><li>Moves broad near-field mounds left and right across both camera views on every terrain generation.</li><li>Places two to nine deterministic pseudo-random static boxes, spheres, and cylinders in each camera&#39;s near field.</li><li>Projects each depth image into world-frame points with <code>DepthCamera::depthToPointCloud</code> and draws every sixth pixel in each direction as a small cube, one <code>InstancedVisuals</code> batch per camera in the color of its frustum (orange front, blue rear), darker with distance. The batches are not detectable, so the cameras never see the cubes.</li><li>Allocates the new heightmap and primitives before calling <code>World::removeObject</code> on the old scene, guaranteeing distinct object addresses while still exercising deletion.</li></ul>',13)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
